"""Exhaust historical priority groups in order, shuffling only within a group."""

import bisect
import hashlib
import itertools
import math
import random
from array import array

from open_instruct import logger_utils

logger = logger_utils.setup_logger(__name__)


def _metadata_value(metadata, path):
    value = metadata
    for part in path.split("."):
        if not isinstance(value, dict):
            return None
        value = value.get(part)
    return value


class PriorityPromptProvider:
    """Visit groups 1, 2, 3, 4 in order within each epoch.

    A seeded permutation within each group fixes each epoch's traversal. No reward feedback or group probabilities affect selection.
    """

    requires_feedback = False

    def __init__(self, dataset, *, field, seed, shuffle, source_field=None, source_weights=None):
        if not isinstance(field, str) or not field.strip():
            raise ValueError("Priority sampling requires a metadata field")
        if dataset is None or not len(dataset):
            raise ValueError("Priority sampling requires a nonempty dataset")
        if (source_field is None) != (source_weights is None):
            raise ValueError("Priority source weighting requires both source_field and source_weights")
        if source_weights is not None:
            if not isinstance(source_field, str) or not source_field.strip():
                raise ValueError("Priority source field must be a nonempty metadata key")
            if not isinstance(source_weights, dict) or not source_weights:
                raise ValueError("Priority source weights must be a nonempty mapping")
            for name, weight in source_weights.items():
                if (
                    not isinstance(name, str)
                    or not name.strip()
                    or type(weight) not in (int, float)
                    or not math.isfinite(weight)
                    or weight <= 0
                ):
                    raise ValueError("Priority source names must be nonempty and weights finite and positive")
            if not math.isfinite(sum(source_weights.values())):
                raise ValueError("Priority source weight total must be finite")
        self.samples = dataset.origin_samples
        rows = [{} for _ in range(4)]
        digest = hashlib.sha256()
        for index, sample in enumerate(self.samples):
            group = (sample.metadata or {}).get(field)
            if type(group) is not int or not 1 <= group <= 4:
                raise ValueError(f"Priority row {index}: metadata.{field} must be an integer in 1..4; got {group!r}")
            source = _metadata_value(sample.metadata, source_field) if source_field else ""
            if source_weights is not None and (not isinstance(source, str) or source not in source_weights):
                raise ValueError(
                    f"Priority row {index}: metadata.{source_field}={source!r} has no configured source weight"
                )
            rows[group - 1].setdefault(source, array("Q")).append(index)
            digest.update(bytes([group]))
            if source_field:
                encoded = source.encode()
                digest.update(len(encoded).to_bytes(8, "little"))
                digest.update(encoded)
        self.counts = [sum(map(len, members.values())) for members in rows]
        self.seed, self.shuffle = seed, shuffle
        self.source_field, self.source_weights = source_field, source_weights
        self.epoch_id = 0
        self.order = self._make_order(0, rows=rows)
        self.source_counts = [{name: len(indices) for name, indices in members.items()} for members in rows]
        self.identity = {
            "kind": "priority/v3",
            "field": field,
            "source_field": source_field,
            "source_weights": dict(source_weights) if source_weights is not None else None,
            "seed": seed,
            "shuffle": shuffle,
            "counts": self.counts,
            "assignments_sha256": digest.hexdigest(),
        }
        self.offset = 0
        if source_weights is not None:
            logger.info(
                "Priority source field=%s weights=%s group_source_counts=%s",
                source_field,
                source_weights,
                self.source_counts,
            )
        logger.info(
            "Priority sampling field=%s group_counts=%s order=1,2,3,4 seed=%s shuffle=%s",
            field,
            self.counts,
            seed,
            shuffle,
        )

    @property
    def sample_offset(self):
        return self.offset

    def _make_order(self, epoch, *, rows=None):
        if rows is None:
            rows = [{} for _ in range(4)]
            for index, sample in enumerate(self.samples):
                group = sample.metadata[self.identity["field"]]
                source = _metadata_value(sample.metadata, self.source_field) if self.source_field else ""
                rows[group - 1].setdefault(source, array("Q")).append(index)
        seed = self.seed if epoch == 0 else f"{self.seed}:epoch:{epoch}"
        order = array("Q")
        for group, members in enumerate(rows, 1):
            for source, indices in members.items():
                if self.shuffle:
                    random.Random(
                        f"{seed}:priority:{group}:{source}" if self.source_field else f"{seed}:priority:{group}"
                    ).shuffle(indices)
            if self.source_weights is None:
                order.extend(members.get("", ()))
            else:
                self._merge_sources(order, members, self.source_weights, seed=f"{seed}:priority-sources:{group}")
        return order

    def _merge_sources(self, order, members, weights, *, seed):
        # Build the weighted merge once, so training-time selection remains a
        # slice and checkpoints need only one offset. Each source keeps its own
        # permutation; only exhausted sources change the active probabilities.
        names = sorted(members)
        offsets = dict.fromkeys(names, 0)
        rng = random.Random(seed)
        cumulative = list(itertools.accumulate(weights[name] for name in names))
        while names:
            index = bisect.bisect_right(cumulative, rng.random() * cumulative[-1]) if len(names) > 1 else 0
            name = names[index]
            offset = offsets[name]
            order.append(members[name][offset])
            offsets[name] = offset + 1
            if offsets[name] == len(members[name]):
                names.pop(index)
                cumulative = list(itertools.accumulate(weights[name] for name in names))

    def next_samples(self, n):
        if type(n) is not int or n < 0:
            raise ValueError("n must be a nonnegative integer")
        result = []
        while n:
            if self.offset == len(self.order):
                epoch = self.epoch_id + 1
                order = self._make_order(epoch)
                self.order, self.epoch_id, self.offset = order, epoch, 0
            take = min(n, len(self.order) - self.offset)
            result.extend(self.samples[index] for index in self.order[self.offset : self.offset + take])
            self.offset += take
            n -= take
        return result

    def feedback(self, records):
        """Historical priority remains fixed throughout the run."""

    def state_dict(self):
        return {**self.identity, "epoch_id": self.epoch_id, "offset": self.offset}

    def load_state_dict(self, state):
        for key, expected in self.identity.items():
            if state.get(key) != expected:
                raise ValueError(f"Priority checkpoint configuration mismatch for {key}")
        epoch = state.get("epoch_id")
        if type(epoch) is not int or epoch < 0:
            raise ValueError("Invalid priority checkpoint epoch")
        offset = state.get("offset")
        if type(offset) is not int or not 0 <= offset <= len(self.order):
            raise ValueError("Invalid priority checkpoint cursor")
        order = self._make_order(epoch) if epoch != self.epoch_id else self.order
        self.order, self.epoch_id, self.offset = order, epoch, offset

"""Bridge replaceable prompt selection to MILES' existing buffered group API."""

import copy
from pathlib import Path

import torch
from miles.utils.types import Sample

from miles.rollout.data_source import RolloutDataSourceWithBuffer, compute_global_dataset_state_path
from open_instruct.miles.rollout import (
    mixture_provider,
    priority_provider,
    prompt_provider,
    remind_provider,
    replay_provider,
)


class ProviderRolloutDataSource(RolloutDataSourceWithBuffer):
    """Keep dataset loading and buffering; delegate fresh prompts to a provider.

    The outer Open Instruct wrapper owns locking and atomic checkpoints with the
    pending-group ledger. Dataset size remains available for MILES' run accounting;
    the provider interface itself does not require epochs or quotas.
    """

    def __init__(self, args, *, provider: prompt_provider.PromptProvider | None = None):
        core = getattr(args, "olmo_core", None)
        if provider is None and getattr(core, "prompt_provider", "shuffle") in ("pools", "priority"):
            loader_args = copy.copy(args)
            if core.prompt_provider == "pools":
                # Initialize upstream buffering without eagerly loading the first source.
                loader_args.rollout_global_dataset = False
            else:
                # Priority owns its within-group shuffle; a global permutation is
                # unused and costs another full inventory traversal at startup.
                loader_args.rollout_shuffle = False
            super().__init__(loader_args)
            self.args = args
        else:
            super().__init__(args)
        if provider is not None:
            self.provider = provider
        elif getattr(core, "prompt_provider", "shuffle") in ("mixture", "pools"):
            self.provider, self.dataset = mixture_provider.load(args, self.dataset)
        elif getattr(core, "prompt_provider", "shuffle") == "priority":
            self.provider = priority_provider.PriorityPromptProvider(
                self.dataset,
                field=core.prompt_priority_field,
                source_field=core.prompt_priority_source_field,
                source_weights=core.prompt_priority_source_weights,
                seed=args.rollout_seed,
                shuffle=bool(args.rollout_shuffle),
            )
        elif getattr(core, "prompt_provider", "shuffle") == "remind":
            self.provider = remind_provider.ReMindPromptProvider(
                lambda: self.dataset,
                shuffle=bool(args.rollout_shuffle),
                seed=args.rollout_seed,
                review_fraction=core.remind_review_fraction,
                enqueue_probability=core.remind_enqueue_probability,
            )
        else:
            self.provider = prompt_provider.ShuffledPromptProvider(
                lambda: self.dataset, shuffle=bool(getattr(args, "rollout_shuffle", False))
            )
        if getattr(core, "prompt_replay_enabled", False) and core.prompt_provider != "pools":
            if self.provider.requires_feedback:
                raise ValueError("Prompt replay supports shuffle or mixture, not another feedback provider")
            if isinstance(self.provider, mixture_provider.MixturePromptProvider):
                templates = []
                for source in self.provider.sources:
                    for original in source["dataset"].origin_samples:
                        sample = copy.copy(original)
                        sample.metadata = (sample.metadata or {}) | {"mixture_source": source["name"]}
                        templates.append(sample)
            else:
                templates = self.dataset.origin_samples if self.dataset is not None else []
            prepared_dataset = self.dataset
            self.provider = replay_provider.ReplayPromptProvider(
                self.provider,
                templates,
                fraction=core.prompt_replay_fraction,
                length_drop=core.prompt_replay_length_drop,
                window=core.prompt_replay_window,
                max_successes=core.prompt_replay_max_successes,
                truncation=core.prompt_replay_truncation,
                dataset_guard=lambda: self.dataset is prepared_dataset,
            )
        self._sync_legacy_cursor()

    def close(self):
        if close := getattr(self.provider, "close", None):
            close()

    def _sync_legacy_cursor(self):
        # These compatibility fields describe fresh-data traversal, not reviews.
        provider = self.provider
        while isinstance(provider, (remind_provider.ReMindPromptProvider, replay_provider.ReplayPromptProvider)):
            provider = provider.base
        if isinstance(provider, (prompt_provider.ShuffledPromptProvider, priority_provider.PriorityPromptProvider)):
            self.epoch_id = provider.epoch_id
            self.sample_offset = provider.sample_offset

    def get_samples(self, num_samples: int) -> list[list[Sample]]:
        if type(num_samples) is not int or num_samples < 0:
            raise ValueError("num_samples must be a nonnegative integer")
        buffered = self.buffer.copy()
        counters = self.sample_group_index, self.sample_index
        provider_state = None
        try:
            groups = self._get_samples_from_buffer(num_samples)
            if len(groups) > num_samples:
                raise ValueError(f"buffer_filter_path returned {len(groups)} groups; requested {num_samples}")
            if len(groups) == num_samples:
                return groups
            snapshot = getattr(self.provider, "selection_state_dict", self.provider.state_dict)
            provider_state = copy.deepcopy(snapshot())
            prompts = self.provider.next_samples(num_samples - len(groups))
            if len(prompts) != num_samples - len(groups):
                raise ValueError("Prompt provider must return exactly the requested number of prompts")
            for prompt in prompts:
                group = []
                for _ in range(self.args.n_samples_per_prompt):
                    sample = copy.deepcopy(prompt)
                    sample.group_index = self.sample_group_index
                    sample.index = self.sample_index
                    self.sample_index += 1
                    group.append(sample)
                self.sample_group_index += 1
                groups.append(group)
        except Exception:
            # A delivery is all-or-nothing, including buffered retries, provider
            # selection state, and IDs assigned during response-group expansion.
            self.buffer[:] = buffered
            self.sample_group_index, self.sample_index = counters
            if provider_state is not None:
                restore = getattr(self.provider, "load_selection_state_dict", self.provider.load_state_dict)
                restore(provider_state)
            raise
        self._sync_legacy_cursor()
        return groups

    def load(self, rollout_id=None):
        if not self.args.rollout_global_dataset or not self.args.load:
            return
        path = Path(compute_global_dataset_state_path(self.args.load, rollout_id=rollout_id))
        if not path.exists():
            return  # The outer wrapper distinguishes a fresh model from unsafe resume.
        state = torch.load(path, map_location="cpu", weights_only=True)
        provider_state = state.get("prompt_provider")
        if provider_state is None:
            if not isinstance(self.provider, prompt_provider.ShuffledPromptProvider):
                raise ValueError("A custom prompt provider cannot restore a legacy shuffle cursor")
            provider_state = self.provider.state_dict() | {
                "epoch_id": state.get("epoch_id", 0),
                "sample_offset": state.get("sample_offset", 0),
            }
        self.provider.load_state_dict(provider_state)
        for key in ("epoch_id", "sample_offset", "sample_group_index", "sample_index", "metadata"):
            if key in state:
                setattr(self, key, state[key])
        # Provider state is authoritative, including in older ReMind checkpoints
        # whose top-level cursor fields were left at zero.
        self._sync_legacy_cursor()

        and options.get("sglang_radix_cache_backend") != validation.POLICY_CACHE_BACKEND
    ):
        raise constraints.error(
