def describe_parser(parser):
    records = []
    for action in parser._actions:
        if isinstance(action, argparse._HelpAction):
            continue
        kind = "value"
        if isinstance(action, argparse.BooleanOptionalAction):
            kind = "boolean"
        elif (
            isinstance(action, (argparse._StoreTrueAction, argparse._StoreFalseAction))
            or type(action).__name__ == "DeprecatedStoreTrueAction"
        ):
            kind = "switch"
        elif isinstance(action, argparse._AppendAction):
            kind = "append"
        elif type(action).__name__ == "DeprecatedStoreConstAction":
            kind = "alias_const"
        elif not isinstance(action, argparse._StoreAction) and type(action).__name__ != "DeprecatedAliasStoreAction":
            kind = "unsupported"
        record = {
            "dest": action.dest,
            "flags": action.option_strings,
            "kind": kind,
            "nargs": action.nargs,
            "type": getattr(action.type, "__name__", None),
        }
        if action.choices is not None:
            record["choices"] = sorted(action.choices, key=str)
        if kind in ("boolean", "switch"):
            record.update(default=action.default, const=action.const)
        if kind == "alias_const":
            record["const"] = action.const_value
        records.append(record)
    return records


def compact_options(records):
    """Omit derivable flags and repeated defaults without dropping parser behavior."""
    result = []
    for record in records:
        record = dict(record)
        if record["flags"] == ["--" + record["dest"].replace("_", "-")]:
            del record["flags"]
        for key, default in (("kind", "value"), ("nargs", None), ("type", None)):
            if record[key] == default:
                del record[key]
        result.append(record)
    return result


def load_schema(path=None):
    """Expand the compact on-disk schema for existing validation and parser checks."""
    schema = json.loads((Path(path) if path is not None else Path(__file__).with_name("options.json")).read_text())
    if schema["schema_version"] != 1:
        raise ValueError("Unsupported MILES option schema version")
    schema["options"] = [
        {"flags": ["--" + record["dest"].replace("_", "-")], "kind": "value", "nargs": None, "type": None, **record}
        for record in schema["options"]
    ]
    return schema


@lru_cache(maxsize=1)
def option_index():
    records = load_schema()["options"]
    index = {}
    for record in records:
        canonical_flag = "--" + record["dest"].replace("_", "-")
        if record["dest"] not in index or canonical_flag in record["flags"]:
            index[record["dest"]] = record
    for record in records:
        for flag in record["flags"]:
            index.setdefault(flag.removeprefix("--").replace("-", "_"), record)
    return index


